'use strict';
(()=>{
const nav=document.createElement('button');nav.innerHTML='<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/></svg><span>Подписки</span>';
const analytics=[...document.querySelectorAll('aside nav button')].find(b=>b.textContent.trim()==='Аналитика');analytics.before(nav);
const page=document.createElement('main');page.hidden=true;page.id='subscriptions-page';page.innerHTML=`<div class="breadcrumb">Коммуникации / Подписки</div><div class="heading"><div><h1>Центр подписок</h1><p>Согласия, источники и история изменений</p></div></div><div class="demo"><b>Без отправки писем</b><span>Ссылки доступны для ручной проверки. Тестовые записи изолированы от реальной базы. Рабочая отписка остановит отправку на email во всех аудиториях.</span></div>
<section class="panel"><h2>Запрос подтверждения</h2><p id="sub-policy"></p><form id="sub-form" class="sub-grid"><label>Email<input name="email" type="email" maxlength="254" required placeholder="recipient@example.invalid"></label><label>Источник запроса<input name="source" maxlength="120" required value="Центр подписок"></label><label>Ссылка на источник (необязательно)<input name="source_url" type="url" maxlength="1000"></label><label>Дата источника (необязательно)<input name="source_at" type="datetime-local"></label><label>Основание / примечание<input name="evidence" maxlength="1000"></label><label class="sub-checkbox"><input name="is_test" type="checkbox" checked> Тестовая запись — не меняет реальные запреты</label><button class="outline" type="submit">Создать запрос и ссылку</button></form><p id="sub-mode-note"></p><p role="status" id="sub-form-status"></p><div id="sub-link"></div></section>
<section class="panel"><h2>Подписки и сведения источников</h2><form id="sub-filters" class="sub-grid"><label>Записи<select id="sub-origin" aria-label="Источник списка"><option value="local">Центр подписок</option><option value="overshop">Импорт Over-shop.kz</option></select></label><label>Поиск email<input id="sub-query" type="search"></label><label>Режим<select id="sub-mode" aria-label="Режим подписок"><option value="all">Все</option><option value="test">Тестовые</option><option value="real">Рабочие</option></select></label><label>Состояние<select id="sub-state" aria-label="Состояние подписки"><option value="">Все состояния</option><option value="pending">Ожидает подтверждения</option><option value="confirmed">Подтверждена</option><option value="revoked">Отозвана</option><option value="inactive">Неактивна (импорт)</option><option value="review">На проверке (импорт)</option><option value="suppressed">Исключена из отправки</option></select></label><button class="outline">Показать</button></form><p>Импортированные сведения показаны отдельно и не превращаются автоматически в новое согласие центра. Подтверждение ссылки без отправки письма не доказывает владение почтовым ящиком.</p><div id="sub-list" class="table-scroll"></div><div class="actions"><button class="outline" id="sub-prev">Назад</button><span id="sub-pagination"></span><button class="outline" id="sub-next">Далее</button></div><p role="status" id="sub-status"></p></section>`;document.body.append(page);
const style=document.createElement('style');style.textContent=`.sub-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px;align-items:end}#subscriptions-page label{display:block;margin:8px 0}#subscriptions-page input:not([type=checkbox]),#subscriptions-page select{display:block;width:100%;box-sizing:border-box}#subscriptions-page button{width:auto;min-height:36px;flex:none}#subscriptions-page .sub-checkbox{display:flex;gap:8px;align-items:center}#subscriptions-page .sub-checkbox input{width:auto}#subscriptions-page td,#subscriptions-page th{padding:12px;text-align:left;word-break:break-word}#subscriptions-page input:focus,#subscriptions-page select:focus{outline:none;border-color:#6BAEE0;box-shadow:0 0 0 2px #0795e918}.sub-link-box{padding:16px;margin:14px 0;background:#edf7fc;border:1px solid #cbddec;border-radius:6px}.sub-link-box input{margin:10px 0}.sub-link-box .actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}`;document.head.append(style);
const $=id=>document.getElementById('sub-'+id),form=$('form');let currentPage=1,request=0;
const labels={pending:'Ожидает подтверждения',confirmed:'Подтверждена',revoked:'Отозвана',requested:'Запрос создан',link_created:'Создана ссылка отписки'};
function text(tag,value){const e=document.createElement(tag);e.textContent=value;return e;}
function date(value){return value?new Date(value).toLocaleString('ru-RU'):'—';}
function modeNote(){$('mode-note').textContent=form.elements.is_test.checked?'Тестовый режим: подтверждение и отписка не изменят реальную базу.':'Рабочий режим: подтверждение и отписка запишут реальные изменения согласия. Отписка добавит запрет отправки во всех аудиториях.';}form.elements.is_test.onchange=modeNote;modeNote();
function showLink(data){const host=$('link');host.replaceChildren();host.className='sub-link-box';host.append(text('strong',(data.subscription.is_test?'Тестовая':'Рабочая')+' ссылка: '+(data.action==='confirm'?'подтверждение':'отписка')),text('p',data.note));const input=document.createElement('input');input.readOnly=true;input.value=data.url;input.setAttribute('aria-label','Ссылка подписки');const actions=document.createElement('div');actions.className='actions';const open=text('a','Открыть ссылку');open.href=data.url;open.target='_blank';open.rel='noopener noreferrer';const copy=text('button','Скопировать');copy.type='button';copy.className='outline';copy.onclick=async()=>{try{await navigator.clipboard.writeText(data.url);$('form-status').textContent='Ссылка скопирована.';}catch{input.select();$('form-status').textContent='Скопируйте выделенную ссылку вручную.';}};actions.append(open,copy);host.append(input,actions,text('p','Действует до: '+date(data.expires_at)));}
function prefill(email){form.elements.email.value=email;form.elements.is_test.checked=true;modeNote();$('form-status').textContent='Заполните источник и создайте новый запрос. По умолчанию выбран тестовый режим.';form.elements.email.focus();}
async function history(id){const d=document.createElement('dialog');d.className='client-dialog';const close=text('button','Закрыть');close.className='outline';close.onclick=()=>d.close();d.append(close);document.body.append(d);d.showModal();d.onclose=()=>d.remove();try{const data=await api('/api/subscriptions/'+id);d.append(text('h2',data.email),text('p',(data.is_test?'Тестовая':'Рабочая')+' · '+data.label),text('p','Источник: '+data.source+' · '+date(data.source_at)),text('p','Запрос: '+date(data.requested_at)+' · Подтверждение: '+date(data.confirmed_at)+' · Отзыв: '+date(data.revoked_at)),text('p','Версия: '+data.consent_version),text('p',data.consent_text),text('p',data.evidence||'Без примечания'),text('h3','История — последние 100 записей'));for(const event of data.history){const details=document.createElement('details');details.append(text('summary',date(event.created_at)+' · '+(labels[event.kind]||event.kind)+' · '+event.source),text('p','Источник: '+event.snapshot.source+' · '+date(event.snapshot.source_at)),text('p',event.snapshot.source_url||'Ссылка источника не указана'),text('p',event.snapshot.evidence||'Без примечания'),text('p',event.snapshot.consent_version+' · '+event.snapshot.consent_text));d.append(details);}}catch(e){d.append(text('p',e.message));}}
async function load(){const token=++request;$('status').textContent='Загрузка…';try{const params=new URLSearchParams({query:$('query').value,origin:$('origin').value,mode:$('mode').value,state:$('state').value,page:String(currentPage)});const data=await api('/api/subscriptions?'+params);if(token!==request)return;$('policy').textContent=data.consent_text;currentPage=data.pagination.page;$('list').replaceChildren();if(!data.subscriptions.length)$('list').textContent='Записи не найдены.';else{const table=document.createElement('table'),head=document.createElement('tr');for(const label of ['Email','Режим / состояние','Источник и дата','Действия'])head.append(text('th',label));table.append(head);for(const row of data.subscriptions){const tr=document.createElement('tr');tr.append(text('td',row.email),text('td',(row.is_test?'Тестовая':'Рабочая / источник')+' · '+row.label),text('td',row.source+' · '+date(row.source_at)));const cell=document.createElement('td'),renew=text('button','Новый запрос');renew.className='outline';renew.onclick=()=>prefill(row.email);cell.append(renew);if(data.origin==='local'){const inspect=text('button','История');inspect.className='outline';inspect.onclick=()=>history(row.id);const unsubscribe=text('button','Ссылка отписки');unsubscribe.className='outline';unsubscribe.onclick=async()=>{unsubscribe.disabled=true;try{const response=await api(`/api/subscriptions/${row.id}/unsubscribe-link`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});showLink(response);$('form-status').textContent='Ссылка создана. Отписка применится только по действию на открытой странице.';await load();}catch(e){$('status').textContent=e.message;}finally{unsubscribe.disabled=false;}};cell.append(inspect,unsubscribe);}else cell.append(text('p',row.note));tr.append(cell);table.append(tr);}$('list').append(table);}$('pagination').textContent=`${data.pagination.page} / ${data.pagination.pages} · записей: ${data.pagination.total}`;$('prev').disabled=!data.pagination.has_previous;$('next').disabled=!data.pagination.has_next;$('status').textContent='';}catch(e){if(token===request)$('status').textContent=e.message;}}
form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const data=Object.fromEntries(new FormData(form));data.is_test=form.elements.is_test.checked;const response=await api('/api/subscriptions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});showLink(response);$('form-status').textContent='Запрос сохранён. Письмо не отправлялось. Для подтверждения откройте ссылку и подтвердите согласие.';$('origin').value='local';$('query').value=data.email;$('state').value='';$('mode').value='all';currentPage=1;await load();}catch(e){$('form-status').textContent=e.message;}finally{button.disabled=false;}};
$('filters').onsubmit=e=>{e.preventDefault();currentPage=1;load();};$('prev').onclick=()=>{currentPage=Math.max(1,currentPage-1);load();};$('next').onclick=()=>{currentPage++;load();};
document.querySelector('aside nav').addEventListener('click',event=>{const target=event.target.closest('button');if(!target||target.disabled)return;if(target===nav){document.querySelectorAll('body>main').forEach(p=>p.hidden=true);page.hidden=false;document.querySelectorAll('aside nav button').forEach(b=>{b.classList.remove('active');b.removeAttribute('aria-current');});nav.classList.add('active');nav.setAttribute('aria-current','page');document.title='Центр подписок';try{sessionStorage.setItem('subscriptions-open','1');}catch{}load();}else{page.hidden=true;try{sessionStorage.removeItem('subscriptions-open');}catch{}}});
window.Subscriptions={open(email){$('query').value=email;prefill(email);const openDialog=document.querySelector('dialog[open]');if(openDialog)openDialog.close();nav.click();}};
const previous=openClient;openClient=async row=>{await previous(row);if(!row.email||!dialog.open||focusedContact?.id!==row.id)return;const button=text('button','Подписки и согласия');button.className='outline';button.onclick=()=>window.Subscriptions.open(row.email);document.getElementById('client-content').append(button);};
try{if(sessionStorage.getItem('subscriptions-open')==='1')nav.click();}catch{}
})();
